function locations(){let a=read("locations");if(!a.length){a=[{id:ID(),name:"Main Shop",address:"",active:true,createdAt:new Date().toISOString()}];write("locations",a)}return a}
function stockMap(){let a=read("stock");if(!a.length){let loc=locations()[0].name;a=items().map(p=>({item:p.name,location:loc,qty:N(p.qty),updatedAt:new Date().toISOString()}));write("stock",a);W("stock_migrated","yes")}return a}
function qtyAt(name,loc){return N(stockMap().find(x=>x.item===name&&x.location===loc)?.qty)}
function setQty(name,loc,qty){let a=stockMap(),x=a.find(v=>v.item===name&&v.location===loc);if(x){x.qty=Math.max(0,N(qty));x.updatedAt=new Date().toISOString()}else a.push({item:name,location:loc,qty:Math.max(0,N(qty)),updatedAt:new Date().toISOString()});write("stock",a)}
function allLocQty(name){return stockMap().filter(x=>x.item===name).reduce((s,x)=>s+N(x.qty),0)}
function ensureLocations(){locations();stockMap()}
function currentLocation(){let s=state(),a=locations();return a.some(x=>x.name===s.location)?s.location:a[0].name}
