window.entTransferForm=()=>{let loc=locations(),opts=loc.map(x=>'<option>'+E(x.name)+'</option>').join(""),prods=items().map(x=>'<option>'+E(x.name)+'</option>').join("");modal("Stock transfer",'<form onsubmit="entSaveTransfer(event)">'+sel("Product","etitem",prods)+sel("From location","efrom",opts)+sel("To location","eto",opts)+field("Quantity","eqty","number","",'min="0.001" step="any" required')+field("Date","edate","date",D(),'required')+field("Reference / note","eref")+'<p><button class="btn primary">Post transfer</button></p></form>')};
window.entSaveTransfer=e=>{e.preventDefault();let item=$("#etitem").value,from=$("#efrom").value,to=$("#eto").value,qty=N($("#eqty").value);if(!item||!from||!to||from===to||qty<=0||qty>qtyAt(item,from))return note("Transfer quantity must be available at the source and locations must differ.");setQty(item,from,qtyAt(item,from)-qty);setQty(item,to,qtyAt(item,to)+qty);let p=items().find(x=>x.name===item);if(p)p.qty=allLocQty(item);P("items",items());let a=read("stock_transfers");a.push({id:ID(),date:$("#edate").value,item,from,to,qty,ref:$("#eref").value.trim()});write("stock_transfers",a);log("transfer","stock",item,qty+" "+from+" → "+to);close();transferPage();note("Stock transfer posted.")};
