window.entSaveQuote=e=>{e.preventDefault();let p=items()[N($("#eqitem").value)],ref=$("#eqref").value.trim(),qty=N($("#eqqty").value),rate=N($("#eqrate").value),discount=N($("#eqdiscount").value),a=read("quotes");if(!p||!ref||!$("#eqparty").value.trim()||qty<=0||rate<0||discount>qty*rate||a.some(x=>x.ref.toLowerCase()===ref.toLowerCase()))return note("Check quotation details, discount and unique quote number.");let x={id:ID(),ref,party:$("#eqparty").value.trim(),date:$("#eqdate").value,valid:$("#eqvalid").value,item:p.name,qty,rate,discount,total:(qty*rate-discount)*(1+N(p.gst)/100),status:"Draft",gst:N(p.gst)};a.push(x);write("quotes",a);log("create","quotation",ref,"Quotation total "+x.total);close();quotePage()};
window.entConvertQuote=id=>{let a=read("quotes"),q=a.find(x=>x.id===id);if(!q)return note("Quotation not found.");if(q.status==="Converted")return note("This quotation was already converted.");if(typeof window.transactionForm!=="function")return note("Sales form is unavailable.");window.transactionForm("sales");$("#tparty").value=q.party;$("#tinvoice").value="SI-"+Date.now().toString().slice(-7);let row=document.querySelector(".txnline");if(!row)return;let idx=items().findIndex(x=>x.name===q.item);if(idx<0)return note("Quoted product no longer exists.");row.querySelector(".txitem").value=String(idx);window.txnRate(row.querySelector(".txitem"));row.querySelector(".txqty").value=q.qty;row.querySelector(".txrate").value=q.rate;row.querySelector(".txdiscount").value=q.discount;window.updateTxnTotals();q.status="Preparing";q.invoice=$("#tinvoice").value;write("quotes",a);log("convert-start","quotation",q.ref,"Prepared sales invoice "+q.invoice);};
