window.entSaveOrder=e=>{e.preventDefault();let p=items()[N($("#eoitem").value)],qty=N($("#eoqty").value),rate=N($("#eorate").value),a=read("sales_orders");if(!p||qty<=0||rate<0||!$("#eoparty").value.trim())return note("Enter a valid customer, product and quantity.");a.push({id:ID(),ref:$("#eoref").value,party:$("#eoparty").value.trim(),date:$("#eodate").value,item:p.name,qty,rate,total:qty*rate,status:"Open"});write("sales_orders",a);log("create","sales order",a[a.length-1].ref,"Order saved");close();orderPage()};
