window.entSaveSupplierScore=e=>{e.preventDefault();let a=read("supplierScores");a.push({supplier:$("#essupplier").value,days:N($("#esdays").value),quality:N($("#esquality").value),note:$("#esnote").value,date:D()});write("supplierScores",a);log("record","supplier score",$("#essupplier").value,"Performance entry");close();supplierPage()};
function reorderPage(){let its=items(),sold={};sales().forEach(t=>(t.lines||[]).forEach(l=>sold[l.item]=(sold[l.item]||0)+N(l.stockQty||l.qty)));let rows=its.map(p=>{let rate=sold[p.name]||0,avg=rate/30,target=Math.ceil(avg*14),suggest=Math.max(0,target-N(p.qty));return {p,avg,target,suggest}}).filter(x=>x.suggest>0).sort((a,b)=>b.suggest-a.suggest);$("#view").innerHTML='<div class="welcome"><div><h1>Smart reorder planner</h1><div class="muted">Suggested replenishment from recorded sales movement</div></div></div>'+table(rows.map(x=>'<tr><td>'+E(x.p.name)+'</td><td>'+N(x.p.qty)+'</td><td>'+x.avg.toFixed(2)+'</td><td>'+x.target+'</td><td><b>'+x.suggest+'</b></td><td>'+M(x.suggest*N(x.p.purchase))+'</td></tr>'),["Product","Current stock","Avg/day (30d)","14-day target","Suggested qty","Estimated cost"])+'<div class="notice">Simple 30-day run-rate estimate. It does not account for seasonality, supplier lead time, open purchase orders or promotions.</div>'+btn("Create purchase order","go('Enterprise Purchase Orders')","btn primary")}
function duePage(){let a=read("due_dates");$("#view").innerHTML='<div class="welcome"><div><h1>Credit control & due dates</h1><div class="muted">Invoice due-date register, customer limits and ageing</div></div>'+btn("＋ Add due date","entDueForm()","btn primary")+'</div>'+table(a.slice().reverse().map(x=>'<tr><td>'+E(x.party)+'</td><td>'+E(x.invoice)+'</td><td>'+E(x.type)+'</td><td>'+M(x.amount)+'</td><td>'+E(x.due)+'</td><td>'+(x.status==="Paid"?"Paid":x.due<D()?"Overdue":"Open")+'</td><td>'+btn("Mark paid","entDuePaid("+JSON.stringify(x.id)+")")+'</td></tr>'),["Party","Invoice","Type","Amount","Due date","Status","Action"])+'<div class="notice">Credit limits are advisory and can be enforced on new sales only when customer profiles have a configured limit. Historical invoices are preserved.</div>'}
window.entDueForm=()=>modal("Add due date",'<form onsubmit="entSaveDue(event)">'+sel("Party type","edtype",'<option>Customer</option><option>Supplier</option>')+field("Party","edparty")+field("Invoice reference","edinvoice")+field("Outstanding amount ₹","edamount","number","0",'min="0.01" step="any" required')+field("Due date","eddue","date",D(),'required')+'<p><button class="btn primary">Save due date</button></p></form>');
window.entSaveDue=e=>{e.preventDefault();let x={id:ID(),type:$("#edtype").value,party:$("#edparty").value.trim(),invoice:$("#edinvoice").value.trim(),amount:N($("#edamount").value),due:$("#eddue").value,status:"Open"};if(!x.party||!x.invoice||x.amount<=0)return note("Complete party, invoice, amount and due date.");let a=read("dueDates");a.push(x);write("dueDates",a);log("create","due date",x.invoice,x.party+" "+x.amount);close();duePage()};
window.entDuePaid=id=>{let a=read("dueDates"),x=a.find(v=>v.id===id);if(x){x.status="Paid";x.paidAt=new Date().toISOString();write("dueDates",a);log("settle","due date",x.invoice,"Marked paid manually");duePage()}};
function creditPage(){let rows=customers().map(c=>{let due=typeof window.partyOutstanding==="function"?window.partyOutstanding("Customer",c.name):0,limit=N(c.creditLimit),tier=c.priceTier||"Retail";return '<tr><td>'+E(c.name)+'</td><td>'+M(due)+'</td><td>'+M(limit)+'</td><td>'+E(tier)+'</td><td>'+((limit>0&&due>limit)?"Over limit":"Within limit")+'</td><td>'+btn("Edit profile","entCustomerProfile("+JSON.stringify(c.name)+")")+'</td></tr>'});$("#view").innerHTML='<div class="welcome"><div><h1>Customer credit control</h1><div class="muted">Credit limits, price tier and outstanding exposure</div></div></div>'+table(rows,["Customer","Outstanding","Credit limit","Price tier","Status","Action"])}
window.entCustomerProfile=name=>{let a=customers(),x=a.find(v=>v.name===name);if(!x)return;modal("Customer credit & price profile",'<form onsubmit="entSaveCustomerProfile(event,'+JSON.stringify(name)+')">'+field("Credit limit ₹","ecLimit","number",x.creditLimit||0,'min="0" step="any"')+field("Default discount %","ecDiscount","number",x.discountPercent||0,'min="0" max="100" step="any"')+sel("Price tier","ecTier",["Retail","Wholesale","Distributor"].map(v=>'<option '+((x.priceTier||"Retail")===v?"selected":"")+'>'+v+'</option>').join(""))+'<p><button class="btn primary">Save profile</button></p></form>')};
window.entSaveCustomerProfile=(e,name)=>{e.preventDefault();let a=customers(),x=a.find(v=>v.name===name);if(x){x.creditLimit=N($("#ecLimit").value);x.discountPercent=N($("#ecDiscount").value);x.priceTier=$("#ecTier").value;P("customers",a);log("update","customer",name,"Credit limit / price tier");close();creditPage()}};
function financePage(){let from=D(),salesTotal=sales().filter(x=>x.date>=from).reduce((s,x)=>s+N(x.total),0),outstanding=customers().reduce((s,c)=>s+(window.partyOutstanding?.("Customer",c.name)||0),0),payables=suppliers().reduce((s,c)=>s+(window.partyOutstanding?.("Supplier",c.name)||0),0),expected=read("due_dates").filter(x=>x.status!=="Paid"&&x.due>=from).reduce((s,x)=>s+N(x.amount),0),due=read("due_dates").filter(x=>x.status!=="Paid"&&x.due<from).reduce((s,x)=>s+N(x.amount),0);$("#view").innerHTML='<div class="welcome"><div><h1>Cash-flow forecast</h1><div class="muted">Estimated near-term position from open balances and due dates</div></div></div><div class="grid"><div class="card"><div class="statlabel">Customer receivables</div><div class="stat">'+M(outstanding)+'</div></div><div class="card"><div class="statlabel">Supplier payables</div><div class="stat">'+M(payables)+'</div></div><div class="card"><div class="statlabel">Future due-date inflow / outflow</div><div class="stat">'+M(expected)+'</div></div><div class="card"><div class="statlabel">Overdue tracked amount</div><div class="stat">'+M(due)+'</div></div></div><div class="notice">This is a planning estimate, not a bank balance or guaranteed forecast. It excludes unrecorded bills, timing risk and cash expenses without due dates.</div>'}
function allocationPage(){let a=read("allocations");$("#view").innerHTML='<div class="welcome"><div><h1>Invoice payment allocation</h1><div class="muted">Map recorded receipts/payments to individual invoices</div></div>'+btn("＋ Allocate payment","entAllocationForm()","btn primary")+'</div>'+table(a.slice().reverse().map(x=>'<tr><td>'+E(x.date)+'</td><td>'+E(x.type)+'</td><td>'+E(x.party)+'</td><td>'+E(x.invoice)+'</td><td>'+M(x.amount)+'</td><td>'+E(x.reference)+'</td></tr>'),["Date","Type","Party","Invoice","Allocated","Payment reference"])+'<div class="notice">Allocation records improve invoice-level tracking but do not change the existing payment ledger balance a second time.</div>'}
window.entAllocationForm=()=>modal("Allocate recorded payment",'<form onsubmit="entSaveAllocation(event)">'+sel("Party type","eatype",'<option>Customer</option><option>Supplier</option>')+field("Party name","eaparty")+field("Invoice number","eainvoice")+field("Allocation amount ₹","eaamount","number","0",'min="0.01" step="any" required')+field("Payment reference","earef")+field("Date","eadate","date",D(),'required')+'<p><button class="btn primary">Save allocation</button></p></form>');
window.entSaveAllocation=e=>{e.preventDefault();let type=$("#eatype").value,party=$("#eaparty").value.trim(),invoice=$("#eainvoice").value.trim(),amount=N($("#eaamount").value),ref=$("#earef").value.trim(),a=read("allocations");if(!party||!invoice||amount<=0)return note("Enter party, invoice and amount.");let tx=(type==="Customer"?sales():purchases()).find(x=>x.invoice===invoice&&x.party===party),paid=payments().filter(x=>x.type===type&&x.party===party).reduce((s,x)=>s+N(x.amount),0);if(!tx)return note("No matching invoice found for this party.");let allocated=a.filter(x=>x.type===type&&x.party===party&&x.invoice===invoice).reduce((s,x)=>s+N(x.amount),0),available=Math.max(0,N(tx.total)-N(tx.paid)-allocated);if(amount>available+0.005)return note("Allocation exceeds the remaining invoice balance.");a.push({id:ID(),type,party,invoice,amount,reference:ref,date:$("#eadate").value});write("allocations",a);log("allocate","payment",invoice,M(amount));close();allocationPage()};
function bankPage(){let a=read("bank"),book=cash();$("#view").innerHTML='<div class="welcome"><div><h1>Bank reconciliation</h1><div class="muted">Match imported bank statement entries with the SmartLedger cashbook</div></div>'+btn("＋ Import statement CSV","entBankImport()","btn")+' '+btn("＋ Add bank entry","entBankForm()","btn primary")+'</div>'+table(a.slice().reverse().map(x=>'<tr><td>'+E(x.date)+'</td><td>'+E(x.description)+'</td><td>'+M(x.amount)+'</td><td>'+E(x.direction)+'</td><td>'+E(x.status||"Unmatched")+'</td><td>'+btn("Match","entMatchBank("+JSON.stringify(x.id)+")")+'</td></tr>'),["Date","Description","Amount","Direction","Status","Action"])+'<div class="notice">Reconciliation compares imported records with recorded cashbook rows. It does not connect directly to a bank account.</div>'}
window.entBankForm=()=>modal("Bank / UPI entry",'<form onsubmit="entSaveBank(event)">'+field("Date","ebdate","date",D(),'required')+field("Description","ebdesc")+field("Amount ₹","ebamount","number","0",'min="0.01" step="any" required')+sel("Direction","ebdir",'<option>Credit</option><option>Debit</option>')+field("Reference","ebref")+'<p><button class="btn primary">Save entry</button></p></form>');
window.entSaveBank=e=>{e.preventDefault();let x={id:ID(),date:$("#ebdate").value,description:$("#ebdesc").value,amount:N($("#ebamount").value),direction:$("#ebdir").value,reference:$("#ebref").value,status:"Unmatched"};if(x.amount<=0)return note("Enter a positive amount.");let a=read("bank");a.push(x);write("bank",a);log("create","bank entry",x.reference,x.direction+" "+x.amount);close();bankPage()};
window.entBankImport=()=>modal("Import bank CSV",'<p>Choose a CSV with columns: date, description, amount, direction, reference.</p><input id="ebfile" type="file" accept=".csv,text/csv"><p><button class="btn primary" onclick="entParseBankCSV()">Preview and import</button></p>');
window.entParseBankCSV=()=>{let f=$("#ebfile").files[0];if(!f)return note("Select a CSV file.");let r=new FileReader();r.onload=()=>{let lines=String(r.result).split(/\r?\n/).filter(Boolean),a=read("bank"),added=0;lines.slice(1).forEach(line=>{let c=line.split(",").map(x=>x.trim().replace(/^"|"$/g,""));if(c.length<4)return;let amount=N(c[2]);if(!c[0]||!amount||!["credit","debit"].includes(c[3].toLowerCase()))return;a.push({id:ID(),date:c[0],description:c[1],amount,direction:c[3].toLowerCase()==="credit"?"Credit":"Debit",reference:c[4]||"",status:"Unmatched"});added++});write("bank",a);log("import","bank statement","CSV",added+" rows");close();bankPage();note(added+" bank rows imported.")};r.readAsText(f)};
window.entMatchBank=id=>{let a=read("bank"),x=a.find(v=>v.id===id);if(!x)return;let candidates=cash().filter(c=>Math.abs(N(c.amount)-x.amount)<0.01&&c.date===x.date);if(!candidates.length)return note("No same-date, same-amount cashbook match found.");x.status="Matched";x.matchedNote=candidates[0].note||"";write("bank",a);let rec=read("reconciliations");rec.push({id:ID(),bankId:id,cashNote:x.matchedNote,matchedAt:new Date().toISOString()});write("reconciliations",rec);log("match","bank entry",id,x.matchedNote);bankPage()};
function valuationPage(){let it=items(),p=purchases(),rows=it.map(x=>{let lines=p.flatMap(t=>(t.lines||[]).filter(l=>l.item===x.name).map(l=>({date:t.date,qty:N(l.stockQty||l.qty),rate:N(l.rate)}))).sort((a,b)=>a.date.localeCompare(b.date)),avg=lines.length?lines.reduce((s,l)=>s+l.qty*l.rate,0)/(lines.reduce((s,l)=>s+l.qty,0)||1):N(x.purchase),last=lines.at(-1)?.rate||N(x.purchase);return '<tr><td>'+E(x.name)+'</td><td>'+N(x.qty)+'</td><td>'+M(x.purchase)+'</td><td>'+M(last)+'</td><td>'+M(avg)+'</td><td>'+M(N(x.qty)*avg)+'</td></tr>'});$("#view").innerHTML='<div class="welcome"><div><h1>Stock valuation & purchase history</h1><div class="muted">Purchase-rate history and weighted average cost estimate</div></div></div>'+table(rows,["Product","Qty","Current cost","Last rate","Weighted average","Stock value"])+'<div class="notice">Legacy product.purchase values are not overwritten. FIFO valuation requires complete historical receipt layers; this view estimates weighted-average cost from available purchase lines.</div>'}
function profitabilityPage(){let it=items(),s=sales(),rows=it.map(p=>{let lines=s.flatMap(t=>(t.lines||[]).filter(l=>l.item===p.name).map(l=>({qty:N(l.qty),revenue:N(l.taxable||l.total),cost:N(l.cost)}))),q=lines.reduce((a,x)=>a+x.qty,0),rev=lines.reduce((a,x)=>a+x.revenue,0),cost=lines.reduce((a,x)=>a+x.cost,0);return '<tr><td>'+E(p.name)+'</td><td>'+q+'</td><td>'+M(rev)+'</td><td>'+M(cost)+'</td><td>'+M(rev-cost)+'</td><td>'+(rev?((rev-cost)/rev*100).toFixed(1):"—")+'%</td></tr>'});$("#view").innerHTML='<div class="welcome"><div><h1>Product profitability</h1><div class="muted">Sales revenue, recorded item cost and margin</div></div></div>'+table(rows,["Product","Sold qty","Revenue","Recorded cost","Gross profit","Margin"])+'<div class="notice">Uses recorded line costs. Historical invoices with missing cost or incomplete item lines can produce incomplete margins.</div>'}
function gstPage(){let s=sales(),p=purchases(),tax=x=>N(x.tax),output=s.reduce((a,x)=>a+tax(x),0),input=p.reduce((a,x)=>a+tax(x),0);$("#view").innerHTML='<div class="welcome"><div><h1>GST return preparation</h1><div class="muted">Working summaries for review before statutory filing</div></div>'+btn("Export GSTR-1 CSV","entGSTExport()","btn primary")+'</div><div class="grid"><div class="card"><div class="statlabel">Output GST recorded</div><div class="stat">'+M(output)+'</div></div><div class="card"><div class="statlabel">Input GST recorded</div><div class="stat">'+M(input)+'</div></div><div class="card"><div class="statlabel">Net GST estimate</div><div class="stat">'+M(output-input)+'</div></div></div><div class="notice">Preparation only; this does not file GSTR-1/GSTR-3B or validate legal eligibility. Verify HSN, place of supply, tax treatment and returns with your tax professional.</div>'}
window.entGSTExport=()=>{let rows=[["Invoice","Date","Customer","GSTIN","Taxable","CGST","SGST","IGST","Total"]];sales().forEach(x=>rows.push([x.invoice,x.date,x.party,"",x.taxable??x.total,x.cgst||0,x.sgst||0,x.igst||0,x.total]));let csv=rows.map(r=>r.map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(",")).join("\r\n");download("SmartLedger-GSTR1-working-"+D()+".csv",csv,"text/csv")};
function download(name,content,type){let b=new Blob([content],{type}),u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function docsPage(){let a=read("documents");$("#view").innerHTML='<div class="welcome"><div><h1>Document centre</h1><div class="muted">Attach and index supplier bills, receipts and supporting files</div></div>'+btn("＋ Add document","entDocForm()","btn primary")+'</div>'+table(a.slice().reverse().map(x=>'<tr><td>'+E(x.date)+'</td><td>'+E(x.title)+'</td><td>'+E(x.category)+'</td><td>'+E(x.fileName)+'</td><td>'+M(x.size/1024)+" KB"+'</td><td><a href="'+x.data+'" download="'+E(x.fileName)+'">Open</a></td></tr>'),["Date","Title","Category","File","Size","Open"])+'<div class="notice">Files are stored on this device and included in JSON backup. Keep attachments small to avoid browser storage limits.</div>'}
window.entDocForm=()=>modal("Add document",'<form onsubmit="entSaveDoc(event)">'+field("Document title","edtit")+sel("Category","edcat",'<option>Purchase bill</option><option>Sales proof</option><option>Receipt</option><option>GST document</option><option>Other</option>')+'<div class="field full"><label>File (max 1.5 MB)</label><input id="edfile" type="file" accept=".pdf,image/*" required></div><p><button class="btn primary">Save document</button></p></form>');
window.entSaveDoc=e=>{e.preventDefault();let f=$("#edfile").files[0];if(!f||f.size>1.5*1024*1024)return note("Select a file under 1.5 MB.");let r=new FileReader();r.onload=()=>{let a=read("documents");a.push({id:ID(),date:D(),title:$("#edtit").value.trim(),category:$("#edcat").value,fileName:f.name,size:f.size,data:r.result});write("documents",a);log("attach","document",f.name,$("#edtit").value);close();docsPage()};r.readAsDataURL(f)};
function peoplePage(){let a=read("sales_people");$("#view").innerHTML='<div class="welcome"><div><h1>Sales team</h1><div class="muted">Salesperson directory and recorded performance</div></div>'+btn("＋ Add salesperson","entPersonForm()","btn primary")+'</div>'+table(a.map(x=>{let rev=sales().filter(t=>t.salesperson===x.name).reduce((s,t)=>s+N(t.total),0);return '<tr><td>'+E(x.name)+'</td><td>'+E(x.phone)+'</td><td>'+M(x.target)+'</td><td>'+M(rev)+'</td><td>'+E(x.active?"Active":"Inactive")+'</td></tr>'}),["Salesperson","Phone","Target","Recorded sales","Status"])}
window.entPersonForm=()=>modal("Add salesperson",'<form onsubmit="entSavePerson(event)">'+field("Name","epname")+field("Phone","epphone")+field("Monthly target ₹","eptarget","number","0",'min="0" step="any"')+'<p><button class="btn primary">Save salesperson</button></p></form>');
window.entSavePerson=e=>{e.preventDefault();let a=read("salesPeople"),name=$("#epname").value.trim();if(!name||a.some(x=>x.name.toLowerCase()===name.toLowerCase()))return note("Enter a unique salesperson name.");a.push({id:ID(),name,phone:$("#epphone").value,target:N($("#eptarget").value),active:true});write("salesPeople",a);log("create","salesperson",name,"Added to sales team");close();peoplePage()};
function automationPage(){let a=read("recurring");$("#view").innerHTML='<div class="welcome"><div><h1>Automation centre</h1><div class="muted">Recurring expense schedules and approval queue</div></div>'+btn("＋ Recurring expense","entRecurringForm()","btn primary")+'</div><h3>Recurring schedules</h3>'+table(a.map(x=>'<tr><td>'+E(x.name)+'</td><td>'+E(x.category)+'</td><td>'+M(x.amount)+'</td><td>'+E(x.frequency)+'</td><td>'+E(x.nextDate)+'</td><td>'+btn("Generate expense","entGenerateRecurring("+JSON.stringify(x.id)+")")+'</td></tr>'),["Schedule","Category","Amount","Frequency","Next date","Action"])+'<h3 class="section">Pending approvals</h3>'+table(read("approvals").filter(x=>x.status==="Pending").map(x=>'<tr><td>'+E(x.kind)+'</td><td>'+E(x.description)+'</td><td>'+M(x.amount)+'</td><td>'+E(x.requestedBy)+'</td><td>'+btn("Approve","entApproval("+JSON.stringify(x.id)+",true)")+' '+btn("Reject","entApproval("+JSON.stringify(x.id)+",false)")+'</td></tr>'),["Type","Description","Amount","Requested by","Decision"])}
window.entRecurringForm=()=>modal("Recurring expense",'<form onsubmit="entSaveRecurring(event)">'+field("Schedule name","ername")+field("Category","ercat")+field("Amount ₹","eramount","number","0",'min="0.01" step="any" required')+sel("Frequency","erfreq",'<option>Weekly</option><option>Monthly</option><option>Quarterly</option>')+field("Next date","ernext","date",D(),'required')+'<p><button class="btn primary">Save schedule</button></p></form>');
window.entSaveRecurring=e=>{e.preventDefault();let a=read("recurring"),x={id:ID(),name:$("#ername").value.trim(),category:$("#ercat").value.trim(),amount:N($("#eramount").value),frequency:$("#erfreq").value,nextDate:$("#ernext").value};if(!x.name||!x.category||x.amount<=0)return note("Complete recurring expense details.");a.push(x);write("recurring",a);log("create","recurring expense",x.name,x.amount+" "+x.frequency);close();automationPage()};
window.entGenerateRecurring=id=>{let a=read("recurring"),x=a.find(v=>v.id===id);if(!x)return;let ex=expenses();ex.push({id:Date.now(),date:D(),category:x.category,note:"Recurring: "+x.name,amount:x.amount});P("expenses",ex);let d=new Date(x.nextDate+"T12:00:00");if(x.frequency==="Weekly")d.setDate(d.getDate()+7);else d.setMonth(d.getMonth()+(x.frequency==="Quarterly"?3:1));x.nextDate=d.toISOString().slice(0,10);write("recurring",a);log("generate","expense",x.name,x.amount);automationPage();note("Expense created. Check the expense register.")};
window.entRequestApproval=()=>modal("Request approval",'<form onsubmit="entSaveApproval(event)">'+sel("Action type","eakind",'<option>Discount</option><option>Purchase</option><option>Sales return</option><option>Stock adjustment</option>')+field("Description","eadesc")+field("Amount / value ₹","eaVal","number","0",'min="0" step="any"')+'<p><button class="btn primary">Submit request</button></p></form>');
