function teamPage(){let roles=read("roles"),branches=read("branches");$("#view").innerHTML='<div class="welcome"><div><h1>Branches, staff roles & access</h1><div class="muted">Local workspace configuration; not a server-enforced permission boundary</div></div>'+btn("＋ Add branch","entBranchForm()","btn primary")+'</div><h3>Branches</h3>'+table(branches.map(x=>'<tr><td>'+E(x.name)+'</td><td>'+E(x.address)+'</td><td>'+E(x.status)+'</td></tr>'),["Branch","Address","Status"])+'<h3 class="section">Local role profiles</h3>'+table(roles.map(x=>'<tr><td>'+E(x.name)+'</td><td>'+E(x.role)+'</td><td>'+E((x.permissions||[]).join(", "))+'</td></tr>'),["Staff","Role","Configured permissions"])+'<div class="notice">Actual multi-user authentication, server-side access control and multi-branch cloud data isolation require backend deployment and security rules. These local profiles do not secure business data from a technically capable user.</div>'}
