window.entRoleForm=()=>modal("Add staff role",'<form onsubmit="entSaveRole(event)">'+field("Staff name","ernam")+sel("Role","erole",'<option>Owner</option><option>Manager</option><option>Accountant</option><option>Salesman</option><option>Cashier</option>')+'<p><button class="btn primary">Save profile</button></p></form>');
