function auditPage(){let a=read("audit");$("#view").innerHTML='<div class="welcome"><div><h1>Audit trail</h1><div class="muted">Enterprise events recorded by this module</div></div>'+btn("Export audit CSV","entExportAudit()","btn primary")+'</div>'+table(a.slice().reverse().slice(0,300).map(x=>'<tr><td>'+E(x.at.replace("T"," ").slice(0,19))+'</td><td>'+E(x.user)+'</td><td>'+E(x.action)+'</td><td>'+E(x.entity)+'</td><td>'+E(x.ref)+'</td><td>'+E(x.details)+'</td></tr>'),["Timestamp","Role","Action","Entity","Reference","Details"])}
window.entExportAudit=()=>download("SmartLedger-Audit-"+D()+".json",JSON.stringify(read("audit"),null,2),"application/json");
function insightPage(){let its=items(),s=sales(),sold={};s.forEach(t=>(t.lines||[]).forEach(l=>sold[l.item]=(sold[l.item]||0)+N(l.qty)));let low=its.filter(p=>N(p.qty)<=N(p.minStock??5)),fast=its.map(p=>({name:p.name,qty:sold[p.name]||0})).sort((a,b)=>b.qty-a.qty).slice(0,10),noMargin=s.flatMap(t=>t.lines||[]).filter(l=>N(l.rate)>0&&N(l.cost)>0&&N(l.rate)<N(l.cost));$("#view").innerHTML='<div class="welcome"><div><h1>AI-ready business insights</h1><div class="muted">Deterministic insights from your saved data; no invented predictions</div></div>'+btn("Ask SmartLedger AI","openAIAssistant()","btn primary")+'</div><div class="grid"><div class="card"><div class="statlabel">Low-stock items</div><div class="stat">'+low.length+'</div></div><div class="card"><div class="statlabel">Sales lines below recorded cost</div><div class="stat">'+noMargin.length+'</div></div><div class="card"><div class="statlabel">Products with sales</div><div class="stat">'+Object.keys(sold).length+'</div></div></div><h3>Fast-moving products</h3>'+table(fast.map(x=>'<tr><td>'+E(x.name)+'</td><td>'+x.qty+'</td></tr>'),["Product","Sold quantity"])+'<div class="notice">Forecasts are based on recorded history only. For statistical AI forecasting, the AI service must be configured and data coverage must be sufficient.</div>'}
function backupPage(){let keys=Object.keys(localStorage).filter(k=>k.startsWith("sl_ent_")),bytes=keys.reduce((s,k)=>s+(localStorage.getItem(k)||"").length,0);$("#view").innerHTML='<div class="welcome"><div><h1>Enterprise backup & recovery</h1><div class="muted">Check local data and create a verified JSON archive</div></div></div><div class="grid"><div class="card"><div class="statlabel">Enterprise registers</div><div class="stat">'+keys.length+'</div></div><div class="card"><div class="statlabel">Approx. storage</div><div class="stat">'+(bytes/1024).toFixed(1)+' KB</div></div></div><div class="card section"><h3>Backup</h3><p>Use the existing Settings → Export backup for the full SmartLedger backup. The enterprise records are account-scoped and mapped into the existing backup schema.</p>'+btn("Export enterprise-only JSON","entBackup()","btn primary")+' <label class="btn">Restore enterprise JSON<input id="entRestore" type="file" accept=".json,application/json" hidden onchange="entRestore(event)"></label></div><div class="notice">Keep a copy outside the phone. Restoring enterprise-only data replaces enterprise registers but does not overwrite sales, purchases or stock.</div>'}
window.entBackup=()=>download("SmartLedger-Enterprise-"+D()+".json",JSON.stringify({app:"SmartLedger Enterprise",version:78,exportedAt:new Date().toISOString(),data:Object.fromEntries(Object.keys(localStorage).filter(k=>k.startsWith("sl_ent_")).map(k=>[k,JSON.parse(localStorage.getItem(k)||"null")]))},null,2),"application/json");
window.entRestore=e=>{let f=e.target.files[0];if(!f||f.size>10*1024*1024)return note("Select a JSON file under 10 MB.");let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(x.app!=="SmartLedger Enterprise"||!x.data||typeof x.data!=="object")throw Error();Object.entries(x.data).forEach(([k,v])=>{if(k.startsWith("sl_ent_"))localStorage.setItem(k,JSON.stringify(v))});log("restore","backup",f.name,"Enterprise backup restored");note("Enterprise records restored. Reloading.");location.reload()}catch(_){note("Backup file is invalid or unsupported.")}};r.readAsText(f)};
function taxDocsPage(){let a=read("tax_documents");$("#view").innerHTML='<div class="welcome"><div><h1>E-invoice & e-way bill workspace</h1><div class="muted">Prepare transport/tax document details for manual portal submission</div></div>'+btn("＋ Prepare document","entTaxDocForm()","btn primary")+'</div>'+table(a.slice().reverse().map(x=>'<tr><td>'+E(x.kind)+'</td><td>'+E(x.invoice)+'</td><td>'+E(x.date)+'</td><td>'+E(x.vehicle||"—")+'</td><td>'+E(x.status)+'</td></tr>'),["Document","Invoice","Date","Vehicle","Status"])+'<div class="notice">No government portal API connection is configured. These are preparation records only; they are not valid IRNs or e-way bills until generated through the authorised GST systems.</div>'}
