window.entSaveTaxDoc=e=>{e.preventDefault();let x={id:ID(),kind:$("#etkind").value,invoice:$("#etinvoice").value.trim(),date:$("#etdate").value,vehicle:$("#etvehicle").value.trim(),transporter:$("#ettrans").value.trim(),status:"Draft"};if(!x.invoice)return note("Enter the source invoice number.");let a=read("tax_documents");a.push(x);write("tax_documents",a);log("create","tax document",x.invoice,x.kind);close();taxDocsPage()};
function forecastPage(){let s=sales(),days=30,tot=0;for(let i=0;i<days;i++){let d=new Date();d.setDate(d.getDate()-i);let key=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);tot+=s.filter(x=>x.date===key).reduce((a,x)=>a+N(x.total),0)}let avg=tot/days,rows=items().map(p=>{let q=s.reduce((a,t)=>a+(t.lines||[]).filter(l=>l.item===p.name).reduce((b,l)=>b+N(l.qty),0),0),per=q/days;return '<tr><td>'+E(p.name)+'</td><td>'+q.toFixed(2)+'</td><td>'+per.toFixed(2)+'</td><td>'+Math.ceil(per*30)+'</td><td>'+N(p.qty)+'</td></tr>'});$("#view").innerHTML='<div class="welcome"><div><h1>Sales and stock forecasting</h1><div class="muted">30-day historical run-rate projection</div></div></div><div class="grid"><div class="card"><div class="statlabel">30-day recorded sales</div><div class="stat">'+M(tot)+'</div></div><div class="card"><div class="statlabel">Average daily sales</div><div class="stat">'+M(avg)+'</div></div><div class="card"><div class="statlabel">Simple 30-day projection</div><div class="stat">'+M(avg*30)+'</div></div></div>'+table(rows,["Product","30d sold","Avg/day","Next 30d estimate","Current stock"])+'<div class="notice">Run-rate estimate only. No seasonality, promotions, supplier lead time or demand model is applied.</div>'}
function remindersPage(){let due=read("due_dates").filter(x=>x.status!=="Paid"),rows=due.map(x=>'<tr><td>'+E(x.party)+'</td><td>'+E(x.invoice)+'</td><td>'+M(x.amount)+'</td><td>'+E(x.due)+'</td><td>'+btn("WhatsApp reminder","entWhatsAppReminder("+JSON.stringify(x.id)+")")+'</td></tr>');$("#view").innerHTML='<div class="welcome"><div><h1>Customer & supplier reminders</h1><div class="muted">Prepare WhatsApp / SMS reminders; sending requires your confirmation</div></div></div>'+table(rows,["Party","Invoice","Amount","Due","Action"])+'<div class="notice">SmartLedger opens a prefilled message. It does not send messages automatically or bypass WhatsApp consent.</div>'}
window.entWhatsAppReminder=id=>{let x=read("due_dates").find(v=>v.id===id);if(!x)return;let msg="Reminder from "+(localStorage.bizname||"SmartLedger")+": "+x.type+" balance for invoice "+x.invoice+" is "+M(x.amount)+", due "+x.due+". Please contact us for payment.";let p=(x.type==="Customer"?customers():suppliers()).find(v=>v.name===x.party),phone=String(p?.phone||"").replace(/\D/g,"");if(phone.length===10)phone="91"+phone;window.open("https://wa.me/"+phone+"?text="+encodeURIComponent(msg),"_blank")};
