function suitePage(){let groups=[["Inventory",0,5],["Sales",5,10],["Purchasing",10,15],["Finance",15,20],["Tax & documents",20,25],["AI & forecasting",25,30],["Automation",30,35],["Enterprise controls",35,40]];$("#view").innerHTML='<div class="welcome"><div><h1>SmartLedger Enterprise Suite</h1><div class="muted">Integrated business workflows · v78</div></div></div><div class="notice">The suite uses SmartLedger’s existing item, invoice, party, payment and expense records. External services requiring credentials or government authorisation are clearly marked as preparation-only.</div>'+groups.map(g=>'<section class="section"><h2>'+g[0]+'</h2><div class="more-grid">'+entries.slice(g[1],g[2]).map(x=>'<button class="more-link" onclick="go('+JSON.stringify(x[1])+')"><span class="more-icon">▦</span><span><b>'+x[0]+'</b><small>'+x[2]+'</small></span><span class="more-arrow">›</span></button>').join("")+'</div></section>').join("")+'<section class="section card"><h2>Additional workflow actions</h2>'+btn("Request approval","entRequestApproval()","btn primary")+' '+btn("Add staff profile","entRoleForm()","btn")+' '+btn("Open existing GST reports","go(\\'Tax Reports\\')","btn")+' '+btn("Open AI assistant","openAIAssistant()","btn")+'</section>'}
