hook("saveReturn",args=>{let k=args[1],a=k==="sales"?G("salesReturns"):G("purchaseReturns"),x=a.slice(-1)[0];if(x){let original=(k==="sales"?sales():purchases()).find(t=>String(t.id)===String(x.originalId)),loc=original?.location||currentLocation();if(k==="sales")setQty(x.item,loc,qtyAt(x.item,loc)+N(x.stockQty||x.qty));else setQty(x.item,loc,Math.max(0,qtyAt(x.item,loc)-N(x.stockQty||x.qty)));let p=items().find(z=>z.name===x.item);if(p){p.qty=allLocQty(x.item);P("items",items())}log("return",k,x.invoice,x.item+" · "+x.qty)}});
const oldTxnRate=window.txnRate;
if(typeof oldTxnRate==="function"&&!oldTxnRate.__ent78){const rateWrap=function(select){const out=oldTxnRate.apply(this,arguments);if(window.currentTxn==="sales"){const row=select.closest(".txnline"),p=items()[N(select.value)],party=$("#tparty")?.value?.trim()||"",c=customers().find(x=>String(x.name).toLowerCase()===party.toLowerCase());if(p&&c){const level=c.priceTier||"Retail",rate=window.smartLedgerPriceFor(p.name,level,party);if(rate>0)row.querySelector(".txrate").value=rate;const discount=N(c.discountPercent);row.querySelector(".txdiscount").value=discount>0?(N(row.querySelector(".txqty").value)*N(row.querySelector(".txrate").value)*discount/100).toFixed(2):"0";window.updateTxnTotals()}}return out};rateWrap.__ent78=true;window.txnRate=rateWrap}
const oldTxnForm=window.transactionForm;
if(typeof oldTxnForm==="function"&&!oldTxnForm.__ent78){const formWrap=function(k){const out=oldTxnForm.apply(this,arguments);if(k==="sales"){const host=$("#txnLines")?.closest("form")?.querySelector(".formgrid");if(host&&!$("#esalesperson")){const box=document.createElement("div");box.className="field";box.innerHTML='<label for="esalesperson">Salesperson (optional)</label><select id="esalesperson"><option value="">Not assigned</option>'+read("salesPeople").filter(x=>x.active!==false).map(x=>'<option>'+E(x.name)+'</option>').join("")+'</select>';host.appendChild(box)}const party=$("#tparty");if(party&&!party.dataset.ent78){party.dataset.ent78="1";["input","change"].forEach(evt=>party.addEventListener(evt,()=>document.querySelectorAll(".txnline .txitem").forEach(select=>{if(select.value!=="")window.txnRate(select)})))}}return out};formWrap.__ent78=true;window.transactionForm=formWrap}
